list_shipping_methods.code:
import com.webcommander.sdk.client.ApiResponse;
import java.util.List;
import java.util.Map;

ApiResponse response = client.shippingMethods().listShippingMethods(Map.of("limit", 20));
Map<?, ?> body = (Map<?, ?>) response.getMap();
for (Object row : (List<?>) body.get("shipping_methods")) {
    Map<?, ?> shippingMethod = (Map<?, ?>) row;
    System.out.println(shippingMethod.get("id") + " " + shippingMethod.get("name") + " " + shippingMethod.get("is_default"));
}
System.out.println(((Map<?, ?>) body.get("pagination")).get("has_next"));

